import { eq } from 'drizzle-orm';
import { db } from '@/db';
import { users } from '@/db/schema';
import data from '@/data/salahPath.json';

// The 30-day "Understand your salah" path, generated by scripts/build-salah-path.mjs.
// Import only from server code (API routes) so the paid days never ship in the client bundle.

export type PathWord = { ar: string; en: string | null; root: string | null };
export type PathLine = { surah: number; surahName: string; ayah: number; unlockDay: number; words: PathWord[] };
export type PathRoot = { root: string; letters: string; meaning: string; quranCount: number; firstIn: string; words: { ar: string; en: string | null; ref: string }[] };
export type PathDay = { day: number; free: boolean; title: string; roots: PathRoot[]; unlocked: string[]; pctSalah: number };

export const PATH = data as unknown as {
  totals: { roots: number; words: number; rootedWords: number; freeDays: number; days: number };
  surahs: { number: number; name: string }[];
  days: PathDay[];
  lines: PathLine[];
};

// A path purchase is recorded on the existing supporter fields: the Checkout Session id is
// stored with this prefix, so a donation alone does not unlock the paid days.
export const PATH_ORDER_PREFIX = 'path:';
export const PATH_PRICE_CENTS = Number(process.env.SALAH_PATH_PRICE_CENTS) || 2900;

export async function hasPathAccess(userId: string | undefined): Promise<boolean> {
  if (!userId) return false;
  if (process.env.NEXT_PUBLIC_UNLOCK_SALAH_PATH === 'true') return true;
  try {
    const [row] = await db.select({ order: users.supporterOrderId, role: users.role }).from(users).where(eq(users.id, userId)).limit(1);
    return row?.role === 'admin' || !!row?.order?.startsWith(PATH_ORDER_PREFIX);
  } catch {
    return false;
  }
}

export function linesFor(day: number): PathLine[] {
  return PATH.lines.filter((l) => l.unlockDay === day);
}
export function linesOf(surah: number): PathLine[] {
  return PATH.lines.filter((l) => l.surah === surah);
}

/** What the paid part of the path contains, for the offer shown to people who haven't bought it. */
export function pathOffer() {
  const free = PATH.days.filter((d) => d.free);
  const lastFree = free[free.length - 1];
  const paidSurahs = PATH.surahs.filter((s) => s.number !== 1).map((s) => s.name);
  return {
    priceCents: PATH_PRICE_CENTS,
    paidDays: PATH.days.length - free.length,
    paidRoots: PATH.totals.roots - free.reduce((n, d) => n + d.roots.length, 0),
    paidSurahs,
    freePct: lastFree?.pctSalah ?? 0,
  };
}
export type PathOfferInfo = ReturnType<typeof pathOffer>;

/** The last salah day each user finished (from growth_events), for emails that follow their progress. */
export async function pathProgressByUser(): Promise<Map<string, { day: number; lastAt: Date }>> {
  const { sql } = await import('drizzle-orm');
  const rows = (await db.execute(sql`
    SELECT user_id, max(day)::int AS day, max(created_at) AS last_at
    FROM growth_events WHERE name = 'day_complete' AND user_id IS NOT NULL AND day IS NOT NULL
    GROUP BY user_id`)) as unknown as { user_id: string; day: number; last_at: string }[];
  return new Map(rows.map((r) => [r.user_id, { day: r.day, lastAt: new Date(r.last_at) }]));
}

/** The first line a day unlocks, in Arabic with its word-by-word English, for emails. */
export function previewLine(day: number): { ar: string; en: string } | null {
  const line = PATH.lines.find((l) => l.unlockDay === day) ?? (day === 7 ? PATH.lines.find((l) => l.surah === 1) : undefined);
  if (!line) return null;
  return { ar: line.words.map((w) => w.ar).join(' '), en: line.words.map((w) => w.en ?? '').filter(Boolean).join(' · ') };
}
